import java.util.*; import java.io.*; public class TestClass { public static void main(String[] args) throws Exception { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); int start = readGrid(br); br.readLine(); int target = readGrid(br); int minOps = Integer.MAX_VALUE; for (int rot = 0; rot < 4; rot++) { int current = rotate(start, rot); for (int flips = 0; flips < 256; flips++) { int transformed = applyFlips(current, flips); if (transformed == target) { int ops = rot + Integer.bitCount(flips); if (ops < minOps) minOps = ops; } } } System.out.println(minOps == Integer.MAX_VALUE ? -1 : minOps); } private static int readGrid(BufferedReader br) throws Exception { int grid = 0; for (int i = 0; i < 4; i++) { String line = br.readLine(); for (int j = 0; j < 4; j++) { if (line.charAt(j) == '1') grid |= (1 << (i * 4 + j)); } } return grid; } private static int rotate(int grid, int times) { int res = grid; for (int k = 0; k < times; k++) { int next = 0; for (int i = 0; i < 4; i++) { for (int j = 0; j < 4; j++) { if ((res & (1 << (i * 4 + j))) != 0) next |= (1 << (j * 4 + (3 - i))); } } res = next; } return res; } private static int applyFlips(int grid, int flips) { int res = grid; for (int i = 0; i < 4; i++) { if ((flips & (1 << i)) != 0) { for (int j = 0; j < 4; j++) res ^= (1 << (i * 4 + j)); } } for (int j = 0; j < 4; j++) { if ((flips & (1 << (4 + j))) != 0) { for (int i = 0; i < 4; i++) res ^= (1 << (i * 4 + j)); } } return res; } }